#include <stdio.h>

int main(void) {
    int values[] = {3, 6, 9};
    int *begin = values;
    int *end = values + 3;
    for (int *p = begin; p != end; ++p) printf("%d\n", *p);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

int main(void) {
    int values[5] = {0};
    int *first = &values[1];
    int *last = &values[4];
    ptrdiff_t distance = last - first;
    printf("%td elements apart\n", distance);
    return 0;
}
